import { useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Star } from 'lucide-react';
import { toast } from 'sonner';
import PlusIcon from '@/components/icons/popups/PlusIcon';
import UserIcon from '@/components/icons/UserIcon';
import CalendarIcon from '@/components/icons/CalendarIcon';
import { Dialog, DialogContent, DialogHeader } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { cn } from '@/lib/utils';
import { AddEmployeeReviewFormValues, AddEmployeeReviewSchema } from './add-employee-schema';
import { AddEmployeeReviewDefaultValues, CRITERIA } from '../../data/configs.data';

type Props = {
    open: boolean;
    onOpenChange: (open: boolean) => void;
    onSaved?: () => void;
};

function StarCriterion({ label, value, onChange }: { label: string; value: number; onChange: (v: number) => void }) {
    return (
        <div className="space-y-2">
            <p className="text-sm font-medium text-primery-blue-900 text-end">{label}</p>
            <div className="flex flex-row-reverse items-center justify-end gap-3 flex-wrap">
                <span className="text-sm text-[#625E74] tabular-nums whitespace-nowrap">
                    5 / {value === 0 ? '—' : value}
                </span>
                <div className="flex flex-row-reverse gap-0.5">
                    {[1, 2, 3, 4, 5].map((star) => (
                        <button
                            key={star}
                            type="button"
                            onClick={() => onChange(star === value ? 0 : star)}
                            className="p-0.5 rounded hover:opacity-90 focus:outline-none focus-visible:ring-2 focus-visible:ring-primery-blue-500"
                            aria-label={`${star} من 5`}
                        >
                            <Star
                                className={cn(
                                    'w-5 h-5 transition-colors',
                                    star <= value ? 'fill-amber-400 text-amber-400' : 'fill-transparent text-gray-300',
                                )}
                            />
                        </button>
                    ))}
                </div>
            </div>
        </div>
    );
}

export default function AddEmployeeReviewDialog({ open, onOpenChange, onSaved }: Props) {
    const form = useForm<AddEmployeeReviewFormValues>({
        resolver: zodResolver(AddEmployeeReviewSchema),
        defaultValues: AddEmployeeReviewDefaultValues,
    });

    useEffect(() => {
        if (open) {
            form.reset(AddEmployeeReviewDefaultValues);
        }
    }, [open]);

    const onSubmit = (data: AddEmployeeReviewFormValues) => {
        toast.success('تم حفظ التقييم بنجاح', { className: 'font-cairo' });
        onSaved?.();
        onOpenChange(false);
    };

    return (
        <Dialog open={open} onOpenChange={onOpenChange}>
            <DialogContent
                showCloseButton={false}
                dir="rtl"
                className="max-w-[920px] max-h-[92vh] overflow-y-auto rounded-lg p-6 sm:p-8 bg-white-blue-50 font-cairo gap-0 border-[#E8E7EA]"
            >
                <DialogHeader className="flex flex-col items-stretch space-y-0">
                    <div className="flex flex-row items-center gap-2 mb-4">
                        <PlusIcon />
                        <h2 className="text-[22px] font-bold text-primery-blue-500">معايير تقييم الموظف</h2>
                    </div>
                    <div className="w-full border-b border-[#D1D1D1]" />
                </DialogHeader>

                <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6 space-y-6">
                        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                            <div className="space-y-5 order-2 lg:order-1">
                                {CRITERIA.map((c) => (
                                    <FormField
                                        key={c.name}
                                        control={form.control}
                                        name={c.name}
                                        render={({ field }) => (
                                            <FormItem>
                                                <FormControl>
                                                    <StarCriterion
                                                        label={c.label}
                                                        value={field.value}
                                                        onChange={field.onChange}
                                                    />
                                                </FormControl>
                                                <FormMessage />
                                            </FormItem>
                                        )}
                                    />
                                ))}
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 order-1 lg:order-2">
                                <FormField
                                    control={form.control}
                                    name="employeeName"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                اسم الموظف
                                            </FormLabel>
                                            <FormControl>
                                                <div className="relative">
                                                    <Input
                                                        {...field}
                                                        className="pe-10 placeholder:text-white-blue-600"
                                                        placeholder="اسم الموظف"
                                                    />
                                                    <UserIcon
                                                        width="20"
                                                        height="20"
                                                        className="absolute end-3 top-1/2 -translate-y-1/2 text-primery-blue-400 pointer-events-none"
                                                    />
                                                </div>
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="employeeCode"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                كود الموظف
                                            </FormLabel>
                                            <FormControl>
                                                <div className="relative">
                                                    <Input
                                                        {...field}
                                                        className="pe-10 placeholder:text-white-blue-600"
                                                        placeholder="كود الموظف"
                                                    />
                                                    <span className="absolute end-3 top-1/2 -translate-y-1/2 text-primery-blue-500 font-bold text-sm pointer-events-none">
                                                        #
                                                    </span>
                                                </div>
                                            </FormControl>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormField
                                    control={form.control}
                                    name="period"
                                    render={({ field }) => (
                                        <FormItem>
                                            <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                                الفترة التقييمية
                                            </FormLabel>
                                            <Select onValueChange={field.onChange} value={field.value}>
                                                <FormControl>
                                                    <SelectTrigger className="relative ps-10 text-start">
                                                        <CalendarIcon
                                                            width="20"
                                                            height="20"
                                                            className="absolute start-3 top-1/2 -translate-y-1/2 text-primery-blue-400 pointer-events-none"
                                                        />
                                                        <SelectValue placeholder="اختر الفترة" />
                                                    </SelectTrigger>
                                                </FormControl>
                                                <SelectContent>
                                                    <SelectItem value="q1-2025">الربع الأول 2025</SelectItem>
                                                    <SelectItem value="q2-2025">الربع الثاني 2025</SelectItem>
                                                    <SelectItem value="q3-2025">الربع الثالث 2025</SelectItem>
                                                    <SelectItem value="q4-2025">الربع الرابع 2025</SelectItem>
                                                </SelectContent>
                                            </Select>
                                            <FormMessage />
                                        </FormItem>
                                    )}
                                />
                                <FormItem>
                                    <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                        المقيم
                                    </FormLabel>
                                    <FormControl>
                                        <Input
                                            readOnly
                                            value="موظف الموارد البشرية"
                                            className="bg-[#F3F4F6] border-[#E5E7EB] cursor-default"
                                        />
                                    </FormControl>
                                </FormItem>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            <FormField
                                control={form.control}
                                name="strengths"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            نقاط القوة
                                        </FormLabel>
                                        <FormControl>
                                            <Textarea
                                                {...field}
                                                rows={4}
                                                placeholder="أذكر أبرز نقاط القوة لدى الموظف"
                                                className="placeholder:text-white-blue-600 min-h-[120px] resize-y"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                            <FormField
                                control={form.control}
                                name="development"
                                render={({ field }) => (
                                    <FormItem>
                                        <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                            مجالات التطوير
                                        </FormLabel>
                                        <FormControl>
                                            <Textarea
                                                {...field}
                                                rows={4}
                                                placeholder="أذكر النقاط التي تحتاج إلى تحسين"
                                                className="placeholder:text-white-blue-600 min-h-[120px] resize-y"
                                            />
                                        </FormControl>
                                        <FormMessage />
                                    </FormItem>
                                )}
                            />
                        </div>

                        <FormField
                            control={form.control}
                            name="goals"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-primery-blue-900 font-medium text-[15px]">
                                        أهداف الفترة القادمة
                                    </FormLabel>
                                    <FormControl>
                                        <Textarea
                                            {...field}
                                            rows={3}
                                            placeholder="حدد الأهداف المقترحة"
                                            className="placeholder:text-white-blue-600 min-h-[100px] resize-y"
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <div className="flex flex-row-reverse gap-4 pt-2">
                            <PrimaryButton type="submit" className="flex-1 text-base font-semibold py-3">
                                اضافة
                            </PrimaryButton>
                            <SecondaryButton
                                type="button"
                                className="flex-1 text-base font-semibold py-3"
                                onClick={() => onOpenChange(false)}
                            >
                                إلغاء
                            </SecondaryButton>
                        </div>
                    </form>
                </Form>
            </DialogContent>
        </Dialog>
    );
}
